import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        opp_last = history[-1][1]
        return 'D' if opp_last == 'D' else 'C'

    # Compute opponent's overall cooperation rate cheaply
    opp_defects = 0
    for _, o in history:
        if o == 'D':
            opp_defects += 1
    opp_coop_rate = (n - opp_defects) / n

    last_opp = history[-1][1]
    prev_opp = history[-2][1]
    last_me = history[-1][0]

    # Endgame: squeeze value in final rounds against cooperative opponents
    if n >= 96:
        if opp_coop_rate > 0.75:
            return 'D'
        return 'D'

    # Persistent defector: defect almost always, rare probe
    if n >= 6:
        recent = history[-6:]
        recent_def = 0
        for _, o in recent:
            if o == 'D':
                recent_def += 1
        if recent_def >= 5 and opp_coop_rate < 0.45:
            if rng.random() < 0.05:
                return 'C'
            return 'D'

    # Two consecutive opponent defections
    if last_opp == 'D' and prev_opp == 'D':
        if n < 8:
            return 'D'
        # If opponent is generally cooperative, forgive after punishment
        if opp_coop_rate > 0.6 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent defected once
    if last_opp == 'D':
        if last_me == 'D':
            # We already retaliated, sometimes return to cooperation
            if opp_coop_rate > 0.5 and rng.random() < 0.7:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated
    if last_opp == 'C':
        # Against very cooperative opponents, occasionally exploit
        if opp_coop_rate > 0.85:
            if n % 13 == 0:
                return 'D'
            return 'C'
        # Against moderately cooperative opponents, stay cooperative
        if opp_coop_rate > 0.5:
            if prev_opp == 'C' and rng.random() < 0.06:
                return 'D'
            return 'C'
        # Against mostly-defecting opponents, defect often but probe
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    return 'C'
